-- Do not edit by hand: change the spec and regenerate.
--
-- ROOT CAUSE
--
-- A cold-runner edge-gated part is routed gate trimming, but it was reported as not costed: the reference stages manualTrimRate (12.7, mm/s in
-- memory/Roto & blow molding) but no gate size. This calculator sizes the edge gate by the standard rule w = n x sqrt(A) / 30 (Pye, Injection Mould
-- Design; n by material in reference/gate-sizing-reference.csv) and times the cut as the gates per cavity x w / manualTrimRate, per part (formula
-- registry F-38, ASSUMED). A helper: the injection engine runs it for the routed gate trimming and charges it at the bench rate.
--
-- This migration creates one global calculator per spec entry (inputs are the
-- values the cost engine seeds, each shown with its source in the calculation
-- trace; calculated fields are the formulas the engine evaluates, it holds
-- none) and links every Plastic Molding catalog operation it computes to its
-- calculator in process_calculator_mappings.
--
-- Requires migration 804 (calculators.retired_at).
-- Self-contained, idempotent, post-checked.

BEGIN;

-- Injection Molding - Gate Trimming
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Injection Molding - Gate Trimming$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Injection Molding - Gate Trimming$q$, 'process', 'single', false, true, true, $q$Gate trimming time per part (formula registry F-38, ASSUMED): the operator cuts each gate of the part at the manual trim rate. The gate width is the edge (standard) gate rule w = n x sqrt(A) / 30 (R.G.W. Pye, Injection Mould Design; w mm, A the cavity surface mm2, n the material constant of reference/gate-sizing-reference.csv); the cut length is that width for each gate per cavity (defaultNumberOfGatesPerCavity); the rate is manualTrimRate (12.7, read as mm/s, its unit in memory/Roto & blow molding). Handling the part is not timed. A helper: the injection engine runs it for the routed gate trimming (cold-runner edge gates; hot tips and sub gates self-de-gate) and charges it at the bench rate.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$Gate trimming time per part (formula registry F-38, ASSUMED): the operator cuts each gate of the part at the manual trim rate. The gate width is the edge (standard) gate rule w = n x sqrt(A) / 30 (R.G.W. Pye, Injection Mould Design; w mm, A the cavity surface mm2, n the material constant of reference/gate-sizing-reference.csv); the cut length is that width for each gate per cavity (defaultNumberOfGatesPerCavity); the rate is manualTrimRate (12.7, read as mm/s, its unit in memory/Roto & blow molding). Handling the part is not timed. A helper: the injection engine runs it for the routed gate trimming (cold-runner edge gates; hot tips and sub gates self-de-gate) and charges it at the bench rate.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Part Surface Area$q$, $q$Part Surface Area (mm²)$q$, $q$number$q$, $q$mm²$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Gate Width Constant$q$, $q$Gate Width Constant$q$, $q$number$q$, $q$$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Gates per Cavity$q$, $q$Gates per Cavity$q$, $q$number$q$, $q$$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Manual Trim Rate$q$, $q$Manual Trim Rate (mm/s)$q$, $q$number$q$, $q$mm/s$q$, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Gate Width$q$, $q$Gate Width (mm)$q$, $q$calculated$q$, $q$mm$q$, NULL, NULL, NULL, $q${Gate Width Constant} * sqrt({Part Surface Area}) / 30$q$, 5, false),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$floor({Gates per Cavity} * {Gate Width} / {Manual Trim Rate} * 100 + 0.5) / 100$q$, 6, false);
END
$calc$;

-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Injection Molding - Gate Trimming$q$, 6, 0)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Plastic Molding$q$ AND (m.is_active OR m.machine_class IS NULL)) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1083: calculators incomplete: %', bad;
  END IF;
END
